 if(/goal|iep|services|meeting purpose|agenda/.test(t)&&scene[0]===2)return [0,'Parent clarifies the meeting purpose','I appreciate that explanation. I want to understand which choices we are making today and when I will see the progress information.'];
 if(/thank|welcome|glad|appreciate/.test(t))return [scene[0],'Team acknowledges your response','Thank you for including our perspective. I would like our next step to be clear so everyone knows how to support '+p.student.split(' ')[0]+'.'];
 return [scene[0],'Stakeholder responds to the plan',scene[0]===1?'I appreciate being asked. I want the plan to reflect what actually helps me in class.':scene[0]===0?'I appreciate the discussion, but please be specific about how we will measure progress and communicate changes.':scene[0]===3?'I can implement strategies in class if we define what data to collect and when to review them.':'Please summarize what the team has agreed to and who is responsible for the next action.'];
