 const coachState=/needs correction/i.test(f.status)?'correction':f.fix?.length?'improve':'on-track';const evidence=s.lastReviewFollowup?[{name:'Response to follow-up',quote:s.revisionChecked&&s.revisionDraft?s.revisionDraft:s.records.at(-1)?.answer||'',expected:'Answer the specific stakeholder concern, then agree on a support, evidence source or next step.'}]:coachEvidenceFor(s.revisionChecked&&s.revisionDraft?s.revisionDraft:s.records.at(-1)?.answer||'',s.records.at(-1)?.stage??s.step);return '<section class="dmLearningFeedback" id="dmLearningFeedback" data-coach-result="'+coachState+'" tabindex="-1"><h3><span class="dmCoachStatus">'+(coachState==='correction'?'✕ Correction needed':coachState==='improve'?'! Improve this response':'✓ On track')+'</span> · Response Coach: '+esc(f.status)+'</h3><p><small>Rule-based learning feedback, not an official WGU/Mursion judgment. '+(f.assisted?'Guided assistance used.':'')+'</small></p><details class="dmCoachDetails" open><summary>Show or hide feedback details</summary><h4>Evidence from your actual answer</h4><p><small>These checks identify relevant wording, not proof of complete mastery. A missing match means the rule did not detect that criterion; your answer may still express it in different words.</small></p><ul class="dmCoachEvidence">'+evidence.map(item=>'<li><b>'+esc(item.name)+':</b> '+(item.quote?'<span class="dmEvidenceFound">Found: “'+esc(item.quote)+'”</span>':'<span class="dmEvidenceMissing">Not detected</span>')+' <small>'+esc(item.expected)+'</small></li>').join('')+'</ul><b>What you did well</b><ul>'+f.good.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul><b>What was wrong or missing</b><ul>'+(f.fix.length?f.fix.map(x=>'<li>'+esc(x)+'</li>').join(''):'<li>No clear factual error detected by these limited checks; verify the full IEP.</li>')+'</ul><p><b>Why this matters in the lesson</b> '+esc(f.lesson||'IEP decisions should be evidence-based, collaborative and measurable.')+'</p><p><b>Specific next improvement</b> '+esc(f.next||'Use the student’s IEP evidence and ask a focused follow-up question.')+'</p><details '+(s.mode==='guided'?'open':'')+'><summary>How to say it better</summary><p>'+esc(f.example)+'</p><small>This is a coaching example, not independent mastery.</small></details></details><div class="dmCoachButtons"><button data-action="revise-last">Practice rewrite (not sent)</button><button data-action="feedback-dismiss">Return to meeting</button></div>'+(s.revising?'<div class="dmRevisionBox"><h4>Practice rewriting your previous answer</h4><p><b>Original answer — unchanged:</b> '+esc(s.records.at(-1)?.answer||'')+'</p><p>This rewrite is practice only. It does not answer another stakeholder question or change your original transcript.</p><label for="dmRevision">Improved wording</label><textarea id="dmRevision" rows="4">'+esc(s.revisionDraft||'')+'</textarea><button data-action="revision-submit">Check practice rewrite</button><button data-action="revision-cancel">Cancel rewrite</button></div>':'')+'</section>';
