function professionalFeedback(answer,clarified,assisted,scene){
 if(professionalConcern(answer))return 'Professional-language repair: this wording could feel blaming, dismissive, or threatening to remove accommodations. Acknowledge the impact; ask how the student experiences the problem; restate the need without blame; and propose a measurable support plan. A response repair is needed.';
 if(s.toneOpen)return 'The relationship still needs repair. Acknowledge Angela’s feelings, apologize for the wording if needed, and affirm that she will help decide next steps.';
 if(clarified)return 'Clarifying follow-up credited: you asked about the meaning of a stakeholder statement. Listen to the answer and confirm your understanding before recommending a change.';
 if(indicators(answer).input)return 'Meaningful input credited: you invited a participant’s specific perspective. Use their response to refine the IEP instead of moving straight to another question.';
 if(/month|fade|remove|independen/.test(answer.toLowerCase())&&/checklist|organizer|support/.test(answer.toLowerCase())&&!/data|evidence|progress|review|monitor/.test(answer.toLowerCase()))return 'Independence strategy needs a safeguard: review prompt counts, independent initiation, work completion and writing quality before adjusting scaffolds. Do not remove accommodations just because time passes.';
 if(assisted)return 'You practiced with a guided example. This is coached rehearsal, not independent demonstration; try a fresh response without options next.';
 if(/thank|hear|understand|appreciate|concern/.test(answer.toLowerCase()))return 'Respectful acknowledgment noted. Next, connect the concern to an actual goal, clarify the student’s perspective, and identify a data-informed follow-up.';
 return 'Practice one response at a time: describe the observable issue, acknowledge the participant, and ask one specific question or propose a clear next step.';
}

function reactiveScriptOptions(){
 const p=person(),first=p.student.split(' ')[0],parent=p.parent.split(' ')[0],teacher=p.teacher,scene=activeScene(),t=String(scene[2]||'').toLowerCase();
 const response=(title,text)=>({title,text});
 if(s.step===0&&/purpose|meeting|agenda|decis|today/.test(t))return [
  response('Explain our purpose clearly','That is a good question. Today we are reviewing how '+first+' is doing in school and deciding which goals, services, and classroom supports will help moving forward. We will talk about strengths first, then areas of need, annual goals, transition planning, and progress updates. I want us to finish by summarizing what we agreed on and any concerns that need follow-up. '+parent+', what is one thing you especially want to understand before we leave?'),
  response('Welcome the whole team','Thank you for bringing that up. I want to make sure this meeting makes sense to everyone, especially '+first+' and the family. Our goal is to discuss what is working, what needs to improve, what support the school can provide, and how we will check progress. Before we move into the details, could each person briefly introduce themselves and explain their role?'),
  response('Invite the student into the meeting','I am glad you asked. We will review the IEP together and decide how to support '+first+' in class and with future plans. I will explain the terms as we go so nobody feels left out. '+first+', I would also like to hear directly from you: what is going well in school right now, and what do you want us to understand about the hard parts?')
 ];
 if(/embarrass|private|signal|prompt|remind/.test(t))return [
  response('Listen to how the student feels',first+', thank you for telling us that. I can see why it would be uncomfortable if help drew everyone’s attention to you. We want you to feel supported, not embarrassed. When you say the reminders make you uncomfortable, what part of the teacher coming over feels most noticeable? That will help us make a better plan.'),
  response('Offer a private support choice','I appreciate you sharing that. What if we tried a private help signal or a digital checklist you could use without calling attention to yourself? We could see whether that helps you get started and check in with you about how it feels. '+first+', would you rather use a card, a quiet message, or something else?'),
  response('Bring the teacher into the solution',teacher+', I appreciate that you were trying to help. Now that we know repeated reminders are uncomfortable for '+first+', could we agree on a more private way to check in? We could track how often help is requested and how assignments are completed, then review that information with the student and family.')
 ];
 if(/write|essay|start|organ|idea|paragraph/.test(t))return [
  response('Clarify the writing difficulty',first+', I hear you saying that you understand the ideas when you talk about them, but writing them down is a different challenge. I do not want to assume what is happening. When you get stuck, is it mostly choosing an idea, putting ideas in order, or writing the first sentence? Could you tell us what it feels like at the start of an assignment?'),
  response('Connect oral strengths to writing','Thank you for explaining that. We could have you talk through or record your ideas, choose the main idea using an organizer, and then write the final paragraphs yourself. That would give you a way to plan without someone completing the work for you. '+teacher+', how could that work in your classroom, and what could we measure to see if it helps?'),
  response('Hear the family perspective',parent+', I want to connect what we are hearing in class to what happens at home. Are there routines that help '+first+' begin a written assignment without needing constant reminders? We can compare those with classroom observations and choose a strategy that feels consistent and useful.')
 ];
 if(/goal|progress|report|data|rubric|score|measure/.test(t))return [
  response('Explain the progress evidence','That is a fair question. We should not expect you to understand progress from one number. We can show actual work samples, compare them to the goal criteria, and explain what '+first+' can now do more independently. We will also clarify when progress updates will be shared. '+parent+', would seeing a completed sample beside an earlier sample help you understand the progress?'),
  response('Ask what specifically concerns the family',parent+', I hear that you are not sure the goal fits what you see. When you say that, are you concerned about the skill we selected, the level of difficulty, or how the school plans to measure progress? I would like us to look at the current information together before making any changes.'),
  response('Agree on classroom measurement',teacher+', I agree that the goal should help with work in the general education classroom, not just a separate test. Could you help us identify two or three regular assignments we can use as work samples? We can track the rubric results and what support was needed, then review the pattern with the family.')
 ];
 if(/future|career|college|training|cost|graphic design|job/.test(t))return [
  response('Center the student’s future plan',first+', your interests matter here. You have told us that you want to explore '+p.career+'. What do you enjoy about that area, and what would you like to learn about it first? We can investigate programs, portfolio or application requirements, and jobs without deciding everything today.'),
  response('Clarify the parent’s concern',parent+', I understand that you want stable opportunities after graduation. When you say you are worried about this path, is the main concern the cost of training, the jobs available afterward, or something else? We can research actual options while making sure '+first+' has a voice in the decision.'),
  response('Assign a practical transition step','I think we can respect both perspectives. Let us agree to research programs related to '+p.career+' as well as other options, including entry requirements and costs. We can decide who will gather that information and when '+first+' and the family will review it together.')
 ];
 return [
  response('Respond and clarify','Thank you for explaining your concern. I want to make sure I have understood you correctly before we choose a solution. Could you give a specific example of when this problem happens and what you would most like to see change? Then we can talk about a support and a way to measure whether it helps.'),
  response('Invite a second perspective','I appreciate you sharing what you have observed. I would also like to make sure we hear from '+first+'. Does that match what you experience, or is there another part of the situation the adults may not be seeing? We can use both perspectives when we decide how to move forward.'),
  response('Move toward an agreement','I think we share the goal of helping '+first+' feel successful and develop independence. We can agree on one support to try, decide who will collect progress information, and set a time to review the result together. '+teacher+', what would be practical to begin using in class?')
 ];
}
function responseChoices(){
const p=person(),first=p.student.split(' ')[0],family=p.parent.split(' ')[0],teacher=p.teacher,career=p.career,strengths=p.strengths.toLowerCase(),topic=activeScene()[2].toLowerCase(),step=s.step;
const fill=t=>t.replaceAll('{first}',first).replaceAll('{family}',family).replaceAll('{teacher}',teacher).replaceAll('{career}',career).replaceAll('{strengths}',strengths);
if((s.pending||s.reply)&&!s.toneOpen&&s.pending?.kind!=='respect-repair')return reactiveScriptOptions();
if(s.pending?.kind==='respect-repair'||s.toneOpen)return [["Apologize and rebuild trust","I want to apologize for how I expressed that. It was not respectful, and I appreciate you telling us how it affected you. Our purpose is to support {first}, not to blame anyone for a learning difficulty. I would like to focus on what happens during the task, which supports help, and what the student wants us to understand. {first}, how did that comment feel to you, and what could we do differently to help you feel heard?"],["Use evidence instead of a label","Thank you for bringing that to my attention. I need to correct the way I described the situation. We should not assume that {first} is unwilling or incapable because writing or starting work is difficult. We can review classroom observations and work samples, discuss which accommodations are useful, and agree on what progress will look like. {family}, what have you noticed at home that would help us make a fairer, more supportive plan?"],["Bring the team back together","I hear that my wording caused concern, and I apologize. I want this meeting to be a safe place for students and families to share their experiences. Let us restate the problem as a skill or access need, not a personal failing. We can work together on one support strategy, identify the evidence we will monitor, and review how {first} feels about it. {teacher}, could you describe the task and what you observe so we can agree on an appropriate next step?"]].map(([title,text])=>({title,text:fill(text)}));
if(step===0)return [["Welcome, introduce, and set the agenda","Good afternoon, everyone, and thank you for being here. I am the special education teacher leading {first}'s IEP meeting today. We will review the student's strengths and current needs, discuss measurable annual goals and classroom supports, look at education and career plans, and agree on how progress updates and next steps will be handled. I want everyone, especially {first} and {family}, to feel comfortable speaking and asking for clarification. Could we go around the table and introduce ourselves and our roles before we begin?"],["Explain the purpose to the family","{family}, thank you for raising that concern. We are here both to understand how {first} is doing now and to make informed decisions about goals and services moving forward. I will explain the information in everyday language and check that we all understand the decisions before we leave. We will also summarize how progress reports will be shared. Before we begin reviewing the IEP, what is the most important concern you want the team to address today?"],["Invite the student from the beginning","{first}, I want you to know that this meeting is about your learning and your future, so your opinions matter. We will talk about what you do well, which school tasks feel difficult, and which supports you prefer. The adults can share observations, but we also want to hear your experience directly. It is okay to disagree or ask us to explain something. Before we begin, what would you like the team to know about your school experience this year?"]].map(([title,text])=>({title,text:fill(text)}));
if(/timer|timed|rush|remove|take away|lose|accommod|organizer/.test(topic))return [["Validate the student and clarify","{first}, thank you for telling us how a timer or a change in supports affects you. I do not want you to feel rushed or worried that a tool you need will disappear. We can encourage independence while keeping necessary accommodations in place. When you say a time limit makes writing harder, what exactly happens to your thinking or confidence? Could you describe an example so we understand what we should change?"],["Explain how progress will guide decisions","I understand the goal of becoming more independent, and I agree that we should measure it. However, using an organizer is not the same thing as depending on an adult to complete an assignment. We should not remove accommodations just because a month has passed. We can track independent task initiation, the number of adult prompts, completion, and the quality of written work across several weeks. Then we can review the evidence with {first} and {family} before the team changes anything."],["Work toward a classroom agreement","{teacher}, I appreciate your concern about how we will know whether the strategies help {first} become more independent. Could you describe when reminders are currently needed, and whether there are times the student starts successfully without them? I suggest trying a student-created checklist, a private help signal, and an accessible graphic organizer. We can collect data on prompt counts and writing samples and review those results together. {first}, which part of that plan feels most comfortable to you?"]].map(([title,text])=>({title,text:fill(text)}));
if(/writing|essay|start|prompt|checklist|embarrass|class|assign|draw|creative/.test(topic))return [["Ask about the specific writing barrier","{first}, I appreciate you explaining that you understand many of the ideas in a class discussion, but getting them onto paper can feel like starting all over again. That helps us identify a specific skill to support instead of making assumptions. When you begin a writing assignment, is the hardest part deciding which idea to use, organizing the sequence, or writing the first sentence? Can you describe what happens before you become stuck?"],["Build on strengths and include the teacher","One strength we should recognize is {first}'s ability in {strengths}. We can use that strength by allowing the student to discuss or record ideas before drafting, organize those ideas visually, and complete the final writing in manageable steps. Those tools support access; they do not replace the expectation that the student learns to write independently. {teacher}, how could we use this approach during regular class assignments, and what work samples could show whether the strategy is helping?"],["Gather family and student perspectives","{family}, you raised a concern about unfinished written assignments, and I want to understand how that looks outside school as well. What routines have helped {first} get started at home without needing constant adult reminders? {first}, I want to hear from you too: which of those strategies feels useful and which would you prefer to change? Once we hear both perspectives, we can agree on a support plan that respects the student's dignity and monitors actual progress."]].map(([title,text])=>({title,text:fill(text)}));
if(/goal|rubric|progress|monitor|data|report|score|assessment/.test(topic))return [["Explain a measurable goal clearly","Thank you for asking how the annual goal will help {first}. I want to describe it in plain language: the specific skill the student will demonstrate, the expected level of performance, and the work or assessments we will use to track growth. For example, we can compare several reading or writing samples using the same rubric rather than relying on one assignment. {family}, which part of this goal or progress measure would you like us to explain with an actual example?"],["Plan meaningful progress updates","I understand that receiving a percentage alone does not show a family what the student can do. We can collect dated classroom samples, compare them to the annual goal criteria, and explain both improvements and areas that still need instruction. We should also agree on when updates will be shared and what will happen if progress stalls. {teacher}, what work samples or observations would give the team the clearest evidence of {first}'s progress in general education?"],["Clarify the family disagreement","{family}, I hear that you may not agree with the proposed goal, and I do not want to move forward without understanding why. When you say it does not match what you are seeing, is your main concern the difficulty level, the skill being targeted, or the way we will measure improvement? We can review current evidence together, document your concern, and decide whether the goal needs adjustment or whether we should arrange a follow-up with additional information."]].map(([title,text])=>({title,text:fill(text)}));
if(/career|college|future|transition|design|graduat|training|job|employment/.test(topic)||step>=6&&step<=8)return [["Center the student in future planning","{first}, I want to make sure the team hears your own ideas about life after high school. You have shared an interest in {career}, and your goals should help you explore that interest in a realistic way. We can look into training programs, entry requirements, and the skills you want to practice this year. Which part of {career} interests you most, and what would you like the team to help you investigate first?"],["Respect the parent's practical concerns","{family}, I understand that you want {first} to have stable options after graduation, and your concerns about cost or employment deserve careful attention. We can compare education programs, training requirements, and career opportunities without dismissing the student's preferred path. When you express worry about this future option, are you most concerned about tuition, job availability, or something else? I would like to assign someone to research those questions and bring the information back to both you and {first}."],["Connect today's goals to tomorrow's opportunities","Our transition plan should connect the annual reading, writing, and organization goals to the skills {first} will need for college, training, or employment. We can identify program requirements, opportunities for exploration, and ways the student can practice asking for helpful supports. {teacher}, what current classroom activities could provide practice in those areas? {first}, does that connection feel meaningful to your goal of pursuing {career}, or would you like us to change part of it?"]].map(([title,text])=>({title,text:fill(text)}));
if(step>=9)return [["Summarize agreements and assign responsibilities","As we approach the end of our meeting, I want to summarize what the team has agreed to and what still requires follow-up. We have discussed {first}'s strengths, current needs, annual goals, accommodations, and transition planning. We need to record who will provide instruction, who will collect progress evidence, and when the family will receive updates. If we have not reached agreement on an issue, we can document it and schedule a further discussion rather than rush a decision. {family}, what remaining concern should we prioritize?"],["Check that the student feels heard","{first}, before we close, I want to make sure the team has understood your preferences. We have talked about the strategies you find helpful and your goals for school and the future, but I do not want us to make decisions without checking with you. Which part of the proposed plan seems most helpful, and is there anything you would like us to adjust? After hearing from you, we will also check that {family} understands the next steps and progress updates."],["Close professionally under time pressure","We have a few minutes left, and I want to use them well. I will briefly restate the agreed goals and supports, identify who will complete each follow-up task, and confirm when progress information will be shared. If a concern remains unresolved, we will document it and set another opportunity to discuss it instead of rushing anyone into agreement. Thank you for sharing your perspectives and keeping {first}'s needs central. {family}, which next step would be most important for me to clarify before we finish?"]].map(([title,text])=>({title,text:fill(text)}));
if(true)return [["Acknowledge and invite a specific perspective","Thank you for sharing that concern. Our goal is not only to help {first} finish assignments but also to support confidence and meaningful participation in general education. We need to understand what happens during the task before choosing a strategy. {teacher}, what have you observed during class, and which supports seem to make the greatest difference? Once we hear that perspective, I would like {first} and {family} to tell us whether it matches what they have experienced."],["Explain and clarify the IEP issue","I want to connect this discussion to {first}'s IEP. We should explain the student's strengths, the specific skill or access need, the support being proposed, and how we will know whether that support is effective. I also want to confirm that I understood the concern correctly. When you described the difficulty, could you give a specific example of when it happens and what the student was asked to do? That information will guide a reasonable next step."],["Build a collaborative action plan","I appreciate that everyone brings a different perspective to this meeting. Instead of choosing one person's view over another, we can identify the shared goal, agree on a strategy to try, and decide what evidence we will collect. We can then review the results with {first} and {family} before changing the plan. {family}, how does that approach fit what you see at home? {first}, what would you change so the supports feel useful and respectful to you?"]].map(([title,text])=>({title,text:fill(text)}));
}
function independentTalkingPoints(){
 const topics=[
 ['Welcome each participant','Introduce yourself and the meeting purpose','Confirm the agenda and invite voices'],
 ['Name the student’s strengths','Include academic and personal interests','Invite student and family additions'],
 ['Describe learning needs','Connect current performance to classroom access','Ask for a specific observation'],
 ['Review current performance','Distinguish strengths from needs','Clarify a concern with an example'],
 ['Discuss reading','Describe a measurable skill and progress evidence','Ask who sees the skill in class'],
 ['Discuss writing','Connect planning, organizing, and written work','Invite student and teacher input'],
 ['Discuss independent work','Discuss initiating, checking, and completing steps','Ask what support feels useful'],
 ['Hear concerns','Acknowledge disagreement without defensiveness','Clarify the concern before next steps'],
 ['Review services and supports','Connect supports to needs and access','Ask what works in class and at home'],
 ['Discuss transition','Center the student’s career and training preferences','Invite family questions'],
 ['Agree on monitoring','Name evidence, frequency, and responsible team members','Check how progress will be shared'],
 ['Close collaboratively','Summarize decisions and unresolved concerns','Confirm responsibilities and next steps']
 ];
 const item=topics[Math.min(s.step,topics.length-1)];
 return '<section class="dmIndependentNotes" aria-label="Independent rehearsal talking points" style="border:1px solid #8c7398;border-radius:12px;background:#fffaf4;padding:12px;margin:12px 0"><b>At-a-glance essentials (not a script)</b><ul>'+item.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul><p><small>Use these as reminders; build your own spoken response. Your wording is not filled in or supplied automatically.</small></p><label for="dmPersonalNotes">Your private, editable notes for this agenda item</label><textarea id="dmPersonalNotes" rows="2" placeholder="Add facts from the IEP, a follow-up question, or your own opening...">'+esc((s.personalNotes||{})[s.step]||'')+'</textarea></section>';
}
const FULL_MOCK=[["Meeting introductions","Welcome everyone. Today we will review Angela’s strengths, needs, measurable IEP goals, supports, transition choices, and next steps. Elena, what would you most like the team to discuss?"],["Celebrate strengths","Angela demonstrates strong math skills and artistic creativity. Mr. Moore, what examples have you observed in class? Angela, what are you proud of?"],["Describe present levels","Angela needs reading-comprehension, writing, and organization supports. We should describe actual classroom evidence without inventing scores. Elena, what have you noticed at home?"],["Invite student voice","Angela, which part of extended writing feels hardest? What support helps you begin your work confidently and independently?"],["Explain annual goals","The reading goal measures inferences supported by two details, at four of five rubric points on four of five assessments. Writing measures a three-paragraph response at eight of ten points on four of five samples. Organization measures starting a three-to-five-step task within five minutes and checking work in four of five opportunities across three weeks."],["Review progress monitoring","We will review reading rubrics, writing samples, and task-initiation logs, communicate progress using the IEP reporting schedule, and adjust instruction if progress stalls. Elena, what information would help you?"],["Explore transition interests","Angela, your interest in graphic design matters. We can compare training, college programs, portfolios, and employment opportunities. What do you most want to explore?"],["Respond to disagreement","Elena, I hear your concern about financial stability and training costs. Angela’s preferred path remains central. We can compare available programs and career outcomes together and assign a follow-up."],["Clarify accommodations","We can bridge the three-paragraph goal to longer class assignments with organizers, chunking, modeling and private feedback. Mr. Moore, which supports work in class and what data should we collect?"],["Assign responsibilities","I will coordinate progress monitoring, Mr. Moore can collect classroom examples, and Mr. Mehta can coordinate resources. Angela and Elena will help select transition priorities. What should we follow up on?"],["Check student understanding","Angela, before finalizing anything, which supports and transition options feel right to you? What would you like us to explain or reconsider?"],["Close the meeting","We reviewed strengths, needs, goals, supports, progress monitoring, and graphic design transition planning. We will share data and follow up on decisions. Does anyone have a concern or need clarification? Thank you."]];
function mockScript(){if(!s.active||!s.fullMock)return '';const item=FULL_MOCK[Math.min(11,s.step)];return '<section class="dmMockGuide"><small>FULL MOCK IEP MEETING • STEP '+(s.step+1)+'/12</small><h3>'+esc(item[0])+'</h3><p><strong>Sentence starter:</strong> '+esc(item[1].split(/[.!?]/)[0])+'.</p><details><summary>Optional complete example · open only when you need it</summary><p>'+esc(item[1])+'</p><button type="button" data-mock-model>Insert sample response</button></details><p><small>Guided rehearsal; sample wording is assisted practice, not independent mastery.</small></p></section>';}
const VOICE_PREFS=[{pattern:/zira|samantha|victoria|ava|jenny|(^|[^a-z])female([^a-z]|$)/i,rate:.94,pitch:1.03},{pattern:/zira|samantha|victoria|ava|jenny|(^|[^a-z])female([^a-z]|$)/i,rate:1.03,pitch:1.19},{pattern:/david|daniel|mark|george|guy|(^|[^a-z])male([^a-z]|$)/i,rate:.93,pitch:.88},{pattern:/david|daniel|mark|george|guy|(^|[^a-z])male([^a-z]|$)/i,rate:.99,pitch:1}];
function speakCouncilParticipant(role,words,button){if(!('speechSynthesis' in window)||typeof SpeechSynthesisUtterance!=='function'){button.textContent='Audio unavailable';return;}const voices=speechSynthesis.getVoices().filter(v=>/^en([_-]|$)/i.test(v.lang||'')),index=Math.min(3,Math.max(0,Number(role)||0)),profile=VOICE_PREFS[index],used=new Set();for(let i=0;i<index;i++){const chosen=voices.find(v=>VOICE_PREFS[i].pattern.test(v.name)&&!used.has(v.voiceURI))||voices.find(v=>!used.has(v.voiceURI));if(chosen)used.add(chosen.voiceURI);}const selected=voices.find(v=>profile.pattern.test(v.name)&&!used.has(v.voiceURI))||voices.find(v=>profile.pattern.test(v.name))||voices.find(v=>!used.has(v.voiceURI))||voices[0],utterance=new SpeechSynthesisUtterance(words);if(selected)utterance.voice=selected;utterance.lang=selected?.lang||'en-US';utterance.rate=profile.rate;utterance.pitch=profile.pitch;const reset=()=>{if(button.isConnected)button.textContent='🔊 Hear stakeholder'};utterance.onend=reset;utterance.onerror=reset;speechSynthesis.cancel();button.textContent='🔈 Speaking…';speechSynthesis.speak(utterance);}
const fullMeetingTurnTemplates=[["Welcome and introductions","Good afternoon, everyone. Thank you for being here for {first}'s annual IEP meeting. I'm the special education teacher, and I'll help us work through the plan together. Before we begin, let's introduce ourselves and share how we work with {first}. Today we'll talk about strengths, what is going well, where support is still needed, the goals for this year, future plans, and how we'll share progress. I want {first} and {family} to feel comfortable stopping me if anything is unclear. {first}, is there something you want us to know before we begin?"],["Strengths and present levels","I'd like to start with what {first} does well. The information we have shows strengths in {strengths}. Those strengths matter because we can use them to make harder tasks more manageable. We are also seeing needs in {needs}. Rather than focus only on what is difficult, I want us to understand how those needs affect work in regular classes. {teacher}, what strengths have you seen in class, and can you share a specific example of when {first} has needed support? {family}, I'll ask for your perspective as well."],["Reading goal and parent input","Let's look at the reading goal first. In everyday terms, {reading}. We would look at repeated work samples and score them using the same criteria, so we can see actual growth rather than guessing from one good or difficult day. The reason for this goal is to help {first} understand reading in regular classes and explain ideas using evidence. {family}, what do you think about this goal based on what you see at home? I'd also like to know if the level or the way we measure it worries you."],["Ask the student about useful supports","{first}, I want to hear from you directly about how school feels. We have talked about the things you do well, but you're the person doing these assignments every day. We are considering supports such as {supports}. We do not want a support to make you feel singled out or embarrassed. Which of those tools actually helps you, and when does a teacher's reminder feel helpful versus frustrating? I want us to make a plan you can use comfortably and independently when possible."],["Explain all three annual goals","I want to review the three annual goals together so everyone knows what we're working toward. For reading: {reading}. For writing: {writing}. For organization and getting started with work: {executive}. Each goal describes something we can observe and measure. The goals work together, because {first} needs to understand the work, organize ideas and complete tasks in regular classes. {teacher}, which parts of these goals best connect with classroom assignments, and is anything missing from your perspective?"],["Progress updates and what if progress stalls","Let's talk about how we will know whether this plan is working. We will use reading assessments, writing samples, and records of task initiation and self-checking, matched to the goal criteria. We will share progress information using the reporting schedule documented in the IEP, and we should confirm that schedule together today. If the data show the student is not progressing, we will look at instruction and accommodations instead of simply waiting for the next annual meeting. {family}, what would make those updates easiest for you to understand?"],["Student's future goals and transition","Now I'd like to talk about life after high school. {first}, you've shared an interest in {career}, and I want to make sure we're planning with you, not just about you. We can explore programs, admissions requirements, portfolio or application work, job opportunities, and the support you may be able to request in further education. We can also connect current reading, writing and organization goals to those next steps. Which part of {career} would you most like to investigate first, and what help would you want from the team?"],["Respond to career disagreement","{family}, thank you for sharing your concerns about the future. Wanting a stable path is understandable, and I don't want to dismiss that. At the same time, {first}'s interests must be part of the plan. We don't need to force an agreement before we've looked at real information. When you say this pathway worries you, are you thinking about cost, job options or the training itself? We can compare {career} with {alternative}, assign someone to research program details and meet again to review the options with {first} involved."],["Connect accommodations to grade-level expectations","{teacher}, I appreciate your question about meeting the expectations of regular classes. The organizer, checklist and other supports are tools for accessing the assignment; they don't mean the student should stop developing writing or other grade-level skills. We can teach the steps, look at actual classwork, and track how much help is needed to begin and complete it. We should make any change to support based on evidence and team discussion, not automatically after a certain number of weeks. Which classroom samples would help us evaluate that progress?"],["Responsibilities and next steps","Before we run out of time, I want to identify what each of us will do. I will coordinate the IEP goals and progress records. {teacher} will help us collect examples from the general education classroom. {first} will be involved in choosing and using the supports that work, and {family} can share what is happening at home. We will also identify who will follow up on transition programs and when those findings will be shared. Mr. Mehta, can you help us confirm the responsibilities and resources needed to carry out this plan?"],["Check student understanding","{first}, before we close, I want to make sure I haven't spent the whole meeting talking about you without checking what you think. We discussed the goals, the supports you prefer, and your plans for {career}. In your own words, which part of the plan sounds most helpful? Is there anything that feels uncomfortable, confusing or different from what you wanted? I want to hear that now so your perspective is included in the decisions we write down."],["Summarize and close","Thank you, everyone. Let me summarize what we've covered: {first}'s strengths and needs, the three annual goals, classroom supports, how progress will be measured and shared, and the next steps for future planning. We will document the team decisions and any concerns we have not resolved. We will also confirm who is responsible for each action and when the family will receive updates. {family}, is there a specific part of the plan you would like me to explain again before we finish? Thank you, {first}, for sharing your perspective, and thank you all for working together today."]];
function fullMeetingTurn(){
 const p=person(),fields={first:p.student.split(' ')[0],family:p.parent.split(' ')[0],teacher:p.teacher,strengths:p.strengths.toLowerCase(),needs:p.needs,supports:p.supports,career:p.career,alternative:p.option,reading:p.goals[0][1],writing:p.goals[1][1],executive:p.goals[2][1]};
 const current=fullMeetingTurnTemplates[Math.min(s.step,11)];
 return {title:current[0],text:current[1].replace(/\{([a-z]+)\}/g,(_,key)=>fields[key]||'')};
}
function fullScriptPanel(){
 if(!s.active||s.mode!=='guided')return '';
 const current=fullMeetingTurn();
 const speaker=peopleNow()[activeScene()[0]][0];
 const model=(s.pending||s.reply)?responseChoices()[0]:{title:current.title,text:current.text};
 return '<section class="dmFullScript" aria-label="Complete meeting script"><details><summary><strong>My complete spoken script · Step '+(s.step+1)+' of 12</strong></summary><p><small>Current speaker: '+esc(speaker)+'. This is a full practice script you can actually say, not just a hint. Adapt it to what the participant just told you.</small></p><blockquote>'+esc(model.text)+'</blockquote><button type="button" data-action="use-full-script">Use this complete response</button><details><summary>View all 12 teacher speaking turns</summary><ol>'+fullMeetingTurnTemplates.map((entry,i)=>'<li><strong>'+esc(entry[0])+'</strong><p>'+esc(entry[1].replace(/\{([a-z]+)\}/g,(_,key)=>({first:person().student.split(' ')[0],family:person().parent.split(' ')[0],teacher:person().teacher,strengths:person().strengths.toLowerCase(),needs:person().needs,supports:person().supports,career:person().career,alternative:person().option,reading:person().goals[0][1],writing:person().goals[1][1],executive:person().goals[2][1]}[key]||'')))+'</p></li>').join('')+'</ol></details></details></section>';
}

function coachedOptions(){
 if(!s.active||s.mode!=='guided')return '';
 return '<section class="dmChoices" aria-label="Guided sample responses"><b>Full example teacher responses</b><p>These model complete things you can say. Choose one, practice speaking it aloud, then edit it in your own voice. Any selected example remains coached, never independent.</p><details><summary>Show three ready-to-say teacher responses</summary><div class="dmChoiceList">'+responseChoices().map((x,i)=>'<button type="button" data-response-choice="'+i+'"><strong>'+esc(x.title)+'</strong><span>'+esc(x.text)+'</span></button>').join('')+'</div></details></section>';
}
function typingPause(){if(s.active&&s.pacing==='typing'&&!s.typingPausedAt)s.typingPausedAt=Date.now();}
function typingResume(){if(s.active&&s.typingPausedAt){s.started+=Date.now()-s.typingPausedAt;s.typingPausedAt=null;}}

function meaningfulResponse(a){const i=indicators(a),words=a.trim().split(/\s+/).length,unique=new Set(norm(a).split(' ')).size,clarify=contextualClarification(a,activeScene()[2]);return ((i.input&&words>=5&&unique>=4)||(clarify&&words>=7&&unique>=6)||(words>=10&&unique>=8)||!!professionalConcern(a))&&!s.records.some(r=>norm(r.answer)===norm(a));}
function commitTurn(a,assisted=false){typingResume();s.undoLastTurn=JSON.parse(JSON.stringify({...s,undoLastTurn:null,redoLastTurn:null,started:0,elapsed:elapsed(),active:false}));s.redoLastTurn=null;const scene=activeScene(),people=peopleNow(),isFollow=!!s.pending,pending=s.pending,answeredStage=s.step;const clarified=contextualClarification(a,localize(scene[2]));const tone=professionalConcern(a);if(tone)s.toneOpen=true;else if(s.toneOpen&&/(i'm sorry|i apologize|sorry|i hear|i understand|thank you)/i.test(a)&&/(support|listen|respect|together|choice|help|plan)/i.test(a))s.toneOpen=false;const contextMatch=!!pending&&!clarified&&!indicators(a).input&&addressesPending(a,pending);s.draft='';s.records.push({speaker:people[scene[0]][0],line:localize(scene[2]),answer:a,core:!isFollow,stage:s.step,valid:true,assisted,contextMatch,professionalToneFlag:tone||null,clarifyingFollowUp:clarified,responseTo:pending?.line||null,at:Date.now()});
 if(s.step===7&&indicators(a).input&&indicators(a).who.includes(0)&&/concern|future|career|education|pathway|training|financial/i.test(a)){s.financialDiscovered=true;}
 if(s.step===7&&resolves(a)){s.concernResolved=true;s.concernStatus=/disagree|unresolved|not agree|differ|remain/i.test(a)?'follow-up scheduled':'options acknowledged';}
 s.last=professionalFeedback(a,clarified,assisted,scene);s.lastReview=learningReview(a,scene,assisted);s.lastReviewStage=answeredStage;s.lastReviewFollowup=isFollow;s.revisionChecked=false;s.revisionDraft='';s.lastScene=scene;s.reviewVisible=true;s.revising=false;
 // A follow-up receives one reply, not another automatically generated follow-up.
 // Guided full mock moves to the next agenda topic after that exchange, while preserving every submitted turn.
 s.pending=isFollow?(clarified&&pending?.kind!=='clarification-response'?(()=>{const reply=contextResponsiveStakeholder(a,scene);return {who:reply[0],line:reply[2],kind:'clarification-response'};})():null):tone?professionalRepairPrompt(tone):clarified?(()=>{const reply=contextResponsiveStakeholder(a,scene);return {who:reply[0],line:reply[2],kind:'clarification-response'};})():classroomResponsivePrompt(a,scene)||followUp(a,s.step);
 s.awaitingReply=!!s.pending;
 s.reply=s.pending?null:s.step===7&&s.concernResolved?[0,'Family follow-up','Thank you for hearing my concern. We can keep differing views, compare real options, and record a next step while Angela’s preference remains central.']:contextResponsiveStakeholder(a,scene);
 if(s.fullMock&&!s.pending&&(s.step!==7||s.concernResolved)){
   s.step=Math.min(12,s.step+1);s.reply=null;s.assistedStage=false;
   // Keep the previous snapshot so Undo can restore the just-completed exchange.
   if(s.step===12){end();return;}
 }
 persist();paint();}
function badges(){const m=meter(),all=s.records.map(r=>r.answer).join(' ');return [m.stakeholders===3?'Voice of the Council':null,m.clarify>=3?'Seeker of Clarity':null,s.concernResolved?'Bridge Builder':null,/(college|postsecondary|training)/i.test(all)&&/(employ|career)/i.test(all)?'Keeper of Futures':null].filter(Boolean);}
const defaultMeeting={mode:'guided',fullMock:false,profile:'angela',storyline:'standard',pacing:'normal',typingPausedAt:null,toneOpen:false,step:0,records:[],started:0,elapsed:0,active:false,done:false,last:'',pending:null};
let s={...defaultMeeting},tick,returnFocus;
