 s={...defaultMeeting,records:[]};
try{let saved=JSON.parse((window.MajickSaveSafety?.records||localStorage).getItem(key));if(saved&&saved.mode)s={...s,...saved,typingPausedAt:null,active:false,resumable:saved.mode==='guided'&&!saved.done&&(saved.resumable||saved.elapsed>0||saved.records?.length>0||!!saved.draft)};}catch(_){}
// Repair previously saved follow-ups produced before speaker and dialogue were paired.
if(s.pending?.who===1&&/^I can collect work samples, but we need to agree which independent skills and prompting levels to record\.$/.test(s.pending.line||''))s.pending.who=3;
 try{const savedReplay=JSON.parse((window.MajickSaveSafety?.records||localStorage).getItem(key+'-replay'));replay=savedReplay?.active&&Array.isArray(savedReplay.queue)?savedReplay:null;}catch(_){replay=null;}
